public class OrderPayloadParser {

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON');
        }

        if (!(parsed instanceof Map)) {
            throw new PayloadException('JSON is not an object');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        Object numberObj = root.get('number');
        if (numberObj == null) {
            throw new PayloadException('Missing or blank number');
        }
        String number = String.valueOf(numberObj);
        if (String.isBlank(number)) {
            throw new PayloadException('Missing or blank number');
        }

        Order order = new Order();
        order.orderNumber = number;
        order.lines = new List<Line>();

        try {
            // date
            Object dateObj = root.get('date');
            if (dateObj != null) {
                order.orderDate = Date.valueOf(String.valueOf(dateObj));
            }

            // currency
            Object currencyObj = root.get('currency');
            if (currencyObj != null) {
                order.currencyCode = String.valueOf(currencyObj);
            }

            // customer
            Object customerObj = root.get('customer');
            if (customerObj instanceof Map) {
                Map<String, Object> customer = (Map<String, Object>) customerObj;
                Object emailObj = customer.get('email');
                if (emailObj != null) {
                    order.customerEmail = String.valueOf(emailObj);
                }
            }

            // lines
            Object linesObj = root.get('lines');
            if (linesObj instanceof List) {
                for (Object lineItem : (List<Object>) linesObj) {
                    if (lineItem instanceof Map) {
                        order.lines.add(parseLine((Map<String, Object>) lineItem));
                    }
                }
            }

            // total
            Decimal total = 0;
            for (Line line : order.lines) {
                total += line.lineTotal;
            }
            order.total = total.setScale(2, System.RoundingMode.HALF_UP);

        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            throw new PayloadException('Error parsing payload: ' + e.getMessage());
        }

        return order;
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line line = new Line();

        // sku
        Object skuObj = lineMap.get('sku');
        if (skuObj == null) {
            throw new PayloadException('Missing sku');
        }
        line.sku = String.valueOf(skuObj);

        // quantity
        Object qtyObj = lineMap.get('quantity');
        Integer qty;
        try {
            if (qtyObj instanceof Integer) {
                qty = (Integer) qtyObj;
            } else if (qtyObj instanceof Decimal) {
                qty = ((Decimal) qtyObj).intValue();
            } else {
                qty = Integer.valueOf(String.valueOf(qtyObj));
            }
        } catch (Exception e) {
            throw new PayloadException('Missing or non-positive quantity');
        }
        if (qty <= 0) {
            throw new PayloadException('Missing or non-positive quantity');
        }
        line.quantity = qty;

        // unitPrice
        Object priceObj = lineMap.get('unitPrice');
        if (priceObj == null) {
            throw new PayloadException('Missing or negative unitPrice');
        }
        Decimal price;
        try {
            price = Decimal.valueOf(String.valueOf(priceObj));
        } catch (Exception e) {
            throw new PayloadException('Missing or negative unitPrice');
        }
        if (price < 0) {
            throw new PayloadException('Missing or negative unitPrice');
        }
        line.unitPrice = price;

        // discount
        Object discountObj = lineMap.get('discount');
        if (discountObj != null) {
            try {
                line.discount = Decimal.valueOf(String.valueOf(discountObj));
            } catch (Exception e) {
                line.discount = 0;
            }
        } else {
            line.discount = 0;
        }

        // lineTotal = quantity * unitPrice * (1 - discount), rounded half up to 2 dp
        Decimal raw = line.quantity * line.unitPrice * (1 - line.discount);
        line.lineTotal = raw.setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object> {
            'number' => order.orderNumber,
            'status' => 'RECEIVED',
            'lineCount' => (order.lines != null ? order.lines.size() : 0),
            'total' => (order.total != null ? order.total : 0)
        };
        return JSON.serialize(ack);
    }
}
