public class PicklistService {

    public class Option {
        public String value { get; set; }
        public String label { get; set; }
        public Boolean isDefault { get; set; }

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {
    }

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object or field API name is null or blank');
        }

        // Case-insensitive object lookup via global describe
        Schema.SObjectType targetType = null;
        for (Schema.SObjectType sType : Schema.getGlobalDescribe().values()) {
            if (sType.getDescribe().getName().equalsIgnoreCase(objectApiName)) {
                targetType = sType;
                break;
            }
        }
        if (targetType == null) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }

        // Case-insensitive field lookup
        Schema.SObjectField targetField = null;
        Map<String, Schema.SObjectField> fieldMap = targetType.getDescribe().fields.getMap();
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(fieldApiName)) {
                targetField = fieldMap.get(key);
                break;
            }
        }
        if (targetField == null) {
            throw new PicklistServiceException('Field does not exist on object: ' + fieldApiName);
        }

        Schema.DescribeFieldResult dfr = targetField.getDescribe();
        if (dfr.getType() != Schema.DisplayType.Picklist
                && dfr.getType() != Schema.DisplayType.MultiPicklist) {
            throw new PicklistServiceException(
                'Field is not a picklist or multi-select picklist: ' + fieldApiName);
        }

        List<Option> result = new List<Option>();
        for (Schema.PicklistEntry pe : dfr.getPicklistValues()) {
            if (pe.isActive()) {
                result.add(new Option(
                    pe.getValue(),
                    pe.getLabel(),
                    pe.isDefaultValue()
                ));
            }
        }
        return result;
    }
}
