    public static Integer publishShipments(List<ShipmentEventPublisher.Shipment> shipments) {
        if (shipments == null || shipments.isEmpty()) {
            return 0;
        }

        List<FB_Shipment_Event__e> platformEvents = new List<FB_Shipment_Event__e>();
        for (Shipment shipment : shipments) {
            if (shipment.orderNumber != null && !shipment.orderNumber.isEmpty()) {
                FB_Shipment_Event__e evt = new FB_Shipment_Event__e();
                evt.Order_Number__c = shipment.orderNumber;
                evt.Tracking_Number__c = shipment.trackingNumber;
                evt.Carrier__c = shipment.carrier;
                platformEvents.add(evt);
            }
        }

        if (platformEvents.isEmpty()) {
            return 0;
        }

        EventBus.Result[] results = EventBus.publish(platformEvents);

        Integer successCount = 0;
        for (EventBus.Result result : results) {
            if (result.isSuccess()) {
                successCount++;
            }
        }
        return successCount;
    }
}
