public class OpportunityPipelineHandler {
    private static Boolean isRunning = false;

    public static void handle() {
        if (isRunning) return;
        isRunning = true;

        try {
            Set<Id> accountIds = new Set<Id>();

            List<Opportunity> newList =
                (Trigger.isInsert || Trigger.isUpdate || Trigger.isUndelete) ? Trigger.new : new List<Opportunity>();
            List<Opportunity> oldList =
                (Trigger.isUpdate || Trigger.isDelete) ? Trigger.old : new List<Opportunity>();

            for (Opportunity opp : newList) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
            for (Opportunity opp : oldList) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }

            if (accountIds.isEmpty()) return;

            Map<Id, List<Opportunity>> openOppsByAccount = new Map<Id, List<Opportunity>>();
            for (Id accId : accountIds) {
                openOppsByAccount.put(accId, new List<Opportunity>());
            }

            for (Opportunity opp : [
                SELECT AccountId, Amount
                FROM Opportunity
                WHERE AccountId IN :accountIds
                  AND IsClosed = false
            ]) {
                if (openOppsByAccount.containsKey(opp.AccountId)) {
                    openOppsByAccount.get(opp.AccountId).add(opp);
                }
            }

            List<Account> accountsToUpdate = new List<Account>();
            for (Id accId : accountIds) {
                Decimal totalAmount = 0;
                Integer oppCount = 0;
                for (Opportunity opp : openOppsByAccount.get(accId)) {
                    oppCount++;
                    if (opp.Amount != null) {
                        totalAmount += opp.Amount;
                    }
                }
                accountsToUpdate.add(
                    new Account(
                        Id = accId,
                        FB_Open_Pipeline__c = totalAmount,
                        FB_Open_Opportunities__c = oppCount
                    )
                );
            }

            if (!accountsToUpdate.isEmpty()) {
                update accountsToUpdate;
            }
        } finally {
            isRunning = false;
        }
    }
}
