public class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errors = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errors;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact c : [SELECT Id, Phone FROM Contact
                          WHERE Id IN :contactIds AND Phone != null]) {
            String cleaned = c.Phone.replaceAll('[^\\d+]', '');
            c.Phone = cleaned;
            contactsToUpdate.add(c);
        }

        if (!contactsToUpdate.isEmpty()) {
            List<Database.SaveResult> results = Database.update(contactsToUpdate, false);

            for (Database.SaveResult sr : results) {
                if (!sr.isSuccess()) {
                    String firstError = '';
                    for (Database.Error err : sr.getErrors()) {
                        firstError = err.getMessage();
                        break;
                    }
                    errors.put(sr.getId(), firstError);
                }
            }
        }

        return errors;
    }
}
