import { LightningElement, api, wire, track } from 'lwc';
import { updateRecord } from 'lightning/uiRecordApi';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import { refreshApex } from '@wire/refreshApex';
import { getContacts } from '@salesforce/apex/ContactController.getContacts';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text', editable: false },
    { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
    { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
    { label: 'Email', fieldName: 'Email', type: 'email', editable: true },
];

export default class AccountContactsTable extends LightningElement {
    @api recordId;

    columns = COLUMNS;
    contacts = [];
    draftValues = [];
    wiredContacts;

    @wire(getContacts, { accountId: '$recordId' })
    wiredContacts(value) {
        this.wiredContacts = value;
        if (value.data) {
            this.contacts = value.data;
        }
    }

    handleSave(event) {
        const records = event.detail.draftValues.map((draft) => {
            return updateRecord({ fields: { ...draft } });
        });

        Promise.all(records)
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Contacts updated',
                        variant: 'success',
                    })
                );
                this.draftValues = [];
                return refreshApex(this.wiredContacts);
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Could not save contacts',
                        variant: 'error',
                        message: error.body ? error.body.message : String(error),
                    })
                );
            });
    }
}
