import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines;
    showError = false;

    editorRefs = [];

    handleAction(event) {
        const action = event.target.dataset.action;
        if (action === 'reset') {
            this.editorRefs.forEach((editor) => editor.reset());
            this.showError = false;
        } else if (action === 'submit') {
            let allValid = true;
            const values = [];
            this.editorRefs.forEach((editor) => {
                const valid = editor.validate();
                if (!valid) {
                    allValid = false;
                }
                values.push(editor.getValue());
            });
            if (allValid) {
                this.showError = false;
                this.dispatchEvent(
                    new CustomEvent('submit', { detail: { lines: values } })
                );
            } else {
                this.showError = true;
            }
        }
    }
}
