        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
        this.clearPollTimer();
    }

    handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            this.loadStats();
            this.startPolling();
        } else {
            this.clearPollTimer();
        }
    };

    startPolling = () => {
        this.clearPollTimer();
        this.pollTimer = window.setTimeout(() => {
            if (this.connected) {
                this.loadStats();
                this.startPolling();
            }
        }, 60000);
    };

    clearPollTimer() {
        if (this.pollTimer) {
            window.clearTimeout(this.pollTimer);
            this.pollTimer = null;
        }
    }

    loadStats = async () => {
        if (this.isLoading) {
            return;
        }
        if (document.visibilityState === 'hidden') {
            return;
        }
        this.isLoading = true;
        try {
            const result = await getQueueStats();
            this.waiting = result.waiting;
            this.longestWaitMinutes = result.longestWaitMinutes;
            this.hasStats = true;
            this.error = undefined;
        } catch (e) {
            this.error = e;
        } finally {
            this.isLoading = false;
        }
    };
}
