import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];
    @api value;

    _activeId;

    connectedCallback() {
        this._syncActive();
    }

    renderedCallback() {
        this._syncActive();
    }

    get optionItems() {
        return this.options.map((opt) => ({
            ...opt,
            _id: this._optId(opt.value),
            _selected: opt.value === this.value,
        }));
    }

    _optId(value) {
        return `opt-${String(value).replace(/[^a-zA-Z0-9]/g, '_')}`;
    }

    _syncActive() {
        let newId;
        const matching = this.options.find((o) => o.value === this.value);
        if (matching) {
            newId = this._optId(matching.value);
        } else if (this.options.length) {
            newId = this._optId(this.options[0].value);
        } else {
            newId = undefined;
        }
        if (this._activeId !== newId) {
            this._activeId = newId;
        }
    }

    handleKeydown(event) {
        const key = event.key;
        if (
            key !== 'ArrowDown' &&
            key !== 'ArrowUp' &&
            key !== 'Home' &&
            key !== 'End' &&
            key !== 'Enter' &&
            key !== ' '
        ) {
            return;
        }
        event.preventDefault();

        const opts = this.options;
        if (!opts.length) {
            return;
        }

        let index = -1;
        for (let i = 0; i < opts.length; i += 1) {
            if (this._optId(opts[i].value) === this._activeId) {
                index = i;
                break;
            }
        }

        if (key === 'ArrowDown') {
            index = Math.min(index + 1, opts.length - 1);
        } else if (key === 'ArrowUp') {
            index = Math.max(index - 1, 0);
        } else if (key === 'Home') {
            index = 0;
        } else if (key === 'End') {
            index = opts.length - 1;
        }

        this._activeId = this._optId(opts[index].value);

        if (key === 'Enter' || key === ' ') {
            this._select(opts[index].value);
        }
    }

    handleClick(event) {
        const li = event.target.closest('li');
        if (!li) {
            return;
        }
        this._select(li.dataset.value);
    }

    _select(newValue) {
        if (this.value === newValue) {
            return;
        }
        this._activeId = this._optId(newValue);
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value: newValue } })
        );
    }
}
