public class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();
        Date today = Date.today();

        // SOQL #1: Load all current primary affiliations for the affected contacts
        Map<Id, List<npe5__Affiliation__c>> contactToPrimaryAffs = new Map<Id, List<npe5__Affiliation__c>>();
        for (npe5__Affiliation__c aff : [
            SELECT Id,
                   npe5__Contact__c,
                   npe5__Organization__c,
                   npe5__Status__c,
                   npe5__Primary__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
              AND npe5__Primary__c = true
              AND npe5__Status__c = 'Current'
        ]) {
            if (!contactToPrimaryAffs.containsKey(aff.npe5__Contact__c)) {
                contactToPrimaryAffs.put(aff.npe5__Contact__c, new List<npe5__Affiliation__c>());
            }
            contactToPrimaryAffs.get(aff.npe5__Contact__c).add(aff);
        }

        List<Contact> contactsToUpdate = new List<Contact>();
        List<npe5__Affiliation__c> affiliationsToUpdate = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();

        for (Id contactId : employerByContactId.keySet()) {
            Id newOrgId = employerByContactId.get(contactId);
            List<npe5__Affiliation__c> currentPrimaryAffs = contactToPrimaryAffs.get(contactId);

            // Check whether the contact is already primarily affiliated to this org
            Boolean alreadyPrimaryToTarget = false;
            if (currentPrimaryAffs != null) {
                for (npe5__Affiliation__c aff : currentPrimaryAffs) {
                    if (aff.npe5__Organization__c == newOrgId) {
                        alreadyPrimaryToTarget = true;
                        break;
                    }
                }
            }

            if (alreadyPrimaryToTarget) {
                // Nothing changes for this contact
                continue;
            }

            // Demote existing primary affiliations to Former
            if (currentPrimaryAffs != null) {
                for (npe5__Affiliation__c aff : currentPrimaryAffs) {
                    aff.npe5__Status__c = 'Former';
                    aff.npe5__EndDate__c = today;
                    aff.npe5__Primary__c = false;
                    affiliationsToUpdate.add(aff);
                }
            }

            // Point the contact's primary affiliation lookup to the new organization
            contactsToUpdate.add(new Contact(
                Id = contactId,
                npsp__Primary_Affiliation__c = newOrgId
            ));

            // Create the new Current, primary affiliation
            affiliationsToInsert.add(new npe5__Affiliation__c(
                npe5__Contact__c = contactId,
                npe5__Organization__c = newOrgId,
                npe5__Status__c = 'Current',
                npe5__Primary__c = true,
                npe5__StartDate__c = today,
                npe5__Role__c = 'Current'
            ));
        }

        // DML #1: Update contacts and demote old affiliations in a single mixed-type call
        List<SObject> recordsToUpdate = new List<SObject>();
        recordsToUpdate.addAll(contactsToUpdate);
        recordsToUpdate.addAll(affiliationsToUpdate);
        if (!recordsToUpdate.isEmpty()) {
            Database.update(recordsToUpdate, false);
        }

        // DML #2: Insert new primary affiliations
        if (!affiliationsToInsert.isEmpty()) {
            Database.insert(affiliationsToInsert, false);
        }
    }
}
