public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {

        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        /* Load the org's Data Import Settings (hierarchy custom setting).
         * The defaults configure contact matching on first name, last name
         * and email, and set donation-matching behaviour. */
        npsp__Data_Import_Settings__c importSettings =
            npsp__Data_Import_Settings__c.getInstance();

        /* ---- Stage one NPSP Data Import record per gift ---- */
        List<npsp__DataImport__c> stagedRecords = new List<npsp__DataImport__c>();

        for (WebGift gift : gifts) {
            npsp__DataImport__c staged = new npsp__DataImport__c();
            staged.npsp__Contact1_Firstname__c   = gift.firstName;
            staged.npsp__Contact1_Lastname__c    = gift.lastName;
            staged.npsp__Contact1_Personal_Email__c = gift.email;
            staged.npsp__Donation_Amount__c      = gift.amount;
            staged.npsp__Donation_Date__c        = gift.giftDate;
            staged.npsp__Donation_Donor__c       = 'Contact1';

            // Apply the org's configured import type from Data Import Settings
            if (importSettings != null) {
                staged.npsp__ImportType__c = importSettings.npsp__DefaultImportType__c;
            }

            stagedRecords.add(staged);
        }

        // Persist all staging records (they remain as the audit trail)
        insert stagedRecords;

        // Preserve input order via an ordered list of staged record Ids
        List<Id> stagedIdsInOrder = new List<Id>();
        for (npsp__DataImport__c staged : stagedRecords) {
            stagedIdsInOrder.add(staged.Id);
        }

        /* ---- Process each staged record via NPSP's Data Import Engine ----
         * Isolate failures so a rejection on one row does not stop the rest. */
        Map<Id, String> caughtErrors = new Map<Id, String>();

        for (npsp__DataImport__c staged : stagedRecords) {
            try {
                npsp.DataImportEngine.importData(staged);
            } catch (Exception e) {
                caughtErrors.put(staged.Id, e.getMessage());
            }
        }

        /* ---- Bulk-read every processed staged record (bulk-safe for 200+) ---- */
        Map<Id, ImportResult> processedResults = new Map<Id, ImportResult>();

        for (npsp__DataImport__c rec : [
            SELECT Id,
                   npsp__Status__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c,
                   npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :stagedIdsInOrder
        ]) {
            ImportResult r = new ImportResult();

            if (rec.npsp__Status__c == 'Imported') {
                r.success        = true;
                r.contactId      = rec.npsp__Contact1Imported__c;
                r.opportunityId  = rec.npsp__DonationImported__c;
                r.errorMessage   = null;
            } else {
                r.success       = false;
                r.contactId     = null;
                r.opportunityId = null;
                r.errorMessage  = rec.npsp__FailureInformation__c != null
                                      ? rec.npsp__FailureInformation__c
                                      : 'NPSP Data Import failed for this record';
            }

            processedResults.put(rec.Id, r);
        }

        /* ---- Assemble results in the original input order ---- */
        for (Id id : stagedIdsInOrder) {
            ImportResult r = processedResults.get(id);

            if (r == null) {
                // Record was not returned by the query (possible if the
                // exception aborted its processing before it was committed)
                r = new ImportResult();
                r.success       = false;
                r.contactId     = null;
                r.opportunityId = null;
                r.errorMessage  = caughtErrors.containsKey(id)
                                      ? caughtErrors.get(id)
                                      : 'NPSP Data Import did not complete';
            }

            results.add(r);
        }

        return results;
    }
}
