Looking at this task, I need to create an Apex service class that maps `GiftRequest` objects to NPSP Enhanced Recurring Donation records, with validation before DML and bulk-safe governor limit compliance.

Key considerations:
- All validation happens before any DML (loop through all requests first, throw on any failure)
- Single `insert` statement for all records (1 DML), no SOQL needed
- Day 31 → set `npsp__Always_Use_Last_Day_Of_Month__c = true`; 29/30 stored literally
- Open-ended when installments is null/0 (don't set installments field); otherwise set it and compute end date
- Return IDs in request order

```apex
public class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // Validate all requests before any DML
        for (GiftRequest req : requests) {
            if (req.contactId == null) {
                throw new RecurringGiftException('Contact ID is null');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('Amount is null or non-positive');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException('dayOfMonth must be between 1 and 31');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('Start date is null');
            }
        }

        // Build list of Recurring Donations (no SOQL, no DML yet)
        List<npe03__Recurring_Donation__c> recurringDonations = new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {
            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();

            // Donor / amount
            rd.npe03__Contact__c = req.contactId;
            rd.npe03__Amount__c = req.amount;

            // Schedule: monthly on dayOfMonth starting at startDate
            rd.npe03__Installment_Period__c = 'Monthly';
            rd.npe03__Schedule_Type__c = 'Scheduled';
            rd.npsp__InstallmentFrequency__c = 'Monthly';
            rd.npsp__Day_of_Month__c = req.dayOfMonth;
            rd.npsp__Always_Use_Last_Day_Of_Month__c = (req.dayOfMonth == 31);
            rd.npsp__StartDate__c = req.startDate;

            // Installments: null/0 = open-ended; otherwise fixed-length
            if (req.installments != null && req.installments != 0) {
                rd.npe03__Installments__c = req.installments;
                rd.npsp__EndDate__c = req.startDate.addMonths(req.installments);
            }

            // Status and payment method
            rd.npsp__Status__c = 'Active';
            rd.npsp__PaymentMethod__c = req.paymentMethod;

            recurringDonations.add(rd);
        }

        // Single DML statement
        insert recurringDonations;

        // Collect Ids in request order
        List<Id> resultIds = new List<Id>();
        for (npe03__Recurring_Donation__c rd : recurringDonations) {
            resultIds.add(rd.Id);
        }

        return resultIds;
    }
}
