public class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        // --- Validation (no data changes yet) ---

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('The percentage map cannot be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null) {
                throw new AllocationException('Percentage for GAU ' + gauId + ' cannot be null.');
            }
            if (percent <= 0) {
                throw new AllocationException('Percentage for GAU ' + gauId + ' must be greater than 0.');
            }
            totalPercent += percent;
        }

        if (totalPercent > 100) {
            throw new AllocationException('Total percentages cannot exceed 100%.');
        }

        // Validate GAU existence and active status
        Set<Id> gauIds = percentByGauId.keySet();
        Map<Id, npsp__General_Accounting_Unit__c> gaus = new Map<Id, npsp__General_Accounting_Unit__c>(
            [SELECT Id, npsp__Active__c
             FROM npsp__General_Accounting_Unit__c
             WHERE Id IN :gauIds]
        );

        for (Id gauId : gauIds) {
            if (!gaus.containsKey(gauId)) {
                throw new AllocationException('GAU ' + gauId + ' does not exist.');
            }
            if (gaus.get(gauId).npsp__Active__c == false) {
                throw new AllocationException('GAU ' + gauId + ' is inactive.');
            }
        }

        // --- Data operations (validated above) ---

        // Query opportunity to get its amount (used indirectly via percent on allocation)
        Opportunity opp = [SELECT Id, Amount FROM Opportunity WHERE Id = :opportunityId];

        // Delete all existing allocations for this opportunity
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        // Create one allocation per map entry
        // npsp__Amount__c is a formula field on the org that auto-calculates
        // as npsp__Opportunity__r.Amount * npsp__Percent__c / 100, so it
        // recalculates automatically when the opportunity amount changes.
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : gauIds) {
            Decimal percent = percentByGauId.get(gauId);
            npsp__Allocation__c allocation = new npsp__Allocation__c();
            allocation.npsp__Opportunity__c = opportunityId;
            allocation.npsp__General_Accounting_Unit__c = gauId;
            allocation.npsp__Percent__c = percent;
            newAllocations.add(allocation);
        }

        insert newAllocations;

        return newAllocations;
    }
}
