public class FamilyService {
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> childIds = parentIdByChildId.keySet();
        Set<Id> parentIds = new Set<Id>(parentIdByChildId.values());

        // Collect keys of existing relationships in either direction
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT Id, npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE (npe4__Contact__c IN :childIds AND npe4__RelatedContact__c IN :parentIds)
               OR (npe4__Contact__c IN :parentIds AND npe4__RelatedContact__c IN :childIds)
        ]) {
            existingPairKeys.add(
                String.valueOf(rel.npe4__Contact__c) + '|' + String.valueOf(rel.npe4__RelatedContact__c)
            );
        }

        // Build only those relationships that do not already exist
        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            String forwardKey  = String.valueOf(childId) + '|' + String.valueOf(parentId);
            String reverseKey  = String.valueOf(parentId) + '|' + String.valueOf(childId);

            if (!existingPairKeys.contains(forwardKey) && !existingPairKeys.contains(reverseKey)) {
                npe4__Relationship__c newRel = new npe4__Relationship__c();
                newRel.npe4__Contact__c         = childId;
                newRel.npe4__RelatedContact__c  = parentId;
                newRel.npe4__Type__c            = 'Parent';
                newRel.npe4__Status__c          = 'Current';
                relationshipsToInsert.add(newRel);
            }
        }

        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }
}
