public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        if (!Schema.SObjectType.FB_Employee__c.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        Schema.DescribeSObjectResult objDescribe = Schema.SObjectType.FB_Employee__c.getDescribe();
        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        List<String> accessibleFields = new List<String>();
        List<String> candidateFields = new List<String>{
            'Id', 'Name', 'Department__c', 'Salary__c', 'Personal_Email__c'
        };

        for (String fieldName : candidateFields) {
            if (fieldMap.containsKey(fieldName)
                    && fieldMap.get(fieldName).getDescribe().isAccessible()) {
                accessibleFields.add(fieldName);
            }
        }

        if (accessibleFields.isEmpty()) {
            return new List<FB_Employee__c>();
        }

        String query = 'SELECT ' + String.join(accessibleFields, ', ')
            + ' FROM FB_Employee__c'
            + ' WITH SECURITY_ENFORCED'
            + ' ORDER BY Name ASC';

        return Database.query(query);
    }
}
