            tasks.add(new Task(
                Subject     = 'Onboard new customer',
                WhatId      = acc.Id,
                OwnerId     = acc.OwnerId,
                ActivityDate = Date.today().addDays(7),
                Status      = 'Not Started',
                Priority    = 'Normal'
            ));
        }

        insert tasks;
    }
}
