public inherited sharing class TA_Contact_Queries {

    private static TA_Contact_Queries instance;

    public Map<Id, Account> accountsById { get; private set; }

    private TA_Contact_Queries() {
        accountsById = new Map<Id, Account>();
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    public inherited sharing class Service implements TriggerAction.BeforeInsert {

        public void beforeInsert(List<SObject> triggerNew) {
            TA_Contact_Queries tq = TA_Contact_Queries.getInstance();
            tq.accountsById = new Map<Id, Account>();

            Set<Id> accountIds = new Set<Id>();
            for (SObject s : triggerNew) {
                Id accountId = (Id) s.get('AccountId');
                if (accountId != null) {
                    accountIds.add(accountId);
                }
            }

            if (!accountIds.isEmpty()) {
                for (Account a : [SELECT Id, BillingStreet, BillingCity, BillingPostalCode, BillingCountry, AccountSource
                                  FROM Account
                                  WHERE Id IN :accountIds]) {
                    tq.accountsById.put(a.Id, a);
                }
            }
        }
    }
}
