public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accounts = TA_Contact_Queries.getInstance().accountsById;

        for (SObject s : triggerNew) {
            Contact c = (Contact) s;

            if (c.AccountId == null || !accounts.containsKey(c.AccountId)) {
                continue;
            }

            if (String.isBlank(c.MailingStreet)
                    && String.isBlank(c.MailingCity)
                    && String.isBlank(c.MailingPostalCode)
                    && String.isBlank(c.MailingCountry)) {
                Account acct = accounts.get(c.AccountId);
                c.MailingStreet = acct.BillingStreet;
                c.MailingCity = acct.BillingCity;
                c.MailingPostalCode = acct.BillingPostalCode;
                c.MailingCountry = acct.BillingCountry;
            }
        }
    }
}
